-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Introdução à Tecnologia da Informação e Comunicação' and a.numero = 4
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 4 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 04', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 04 (10 questões discursivas)',
      '/MATERIAIS/ASSISTENTE-DE-OPERACOES-LOGISTICAS/INTRODUCAO-TIC/ATIVIDADES/ATIVIDADE-PRATICA-AULA-04.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Escreva o assunto de um e-mail que solicita à transportadora Rápido Sul a coleta de 12 paletes do pedido 4587 para amanhã, 03/10.', 0.5, 'Exemplo: "[Expedição - Pedido 4587] Solicitação de coleta de 12 paletes – Coleta em 03/10". Precisa ter o setor ou projeto entre colchetes, o assunto (coleta do pedido) e a ação ou prazo (data da coleta).', 'Nota cheia: as três partes da fórmula (setor/projeto, assunto, ação/prazo) com dados do caso. Metade: falta uma das partes. Zero: assunto vago ou sem relação com o caso.'),
      (v_atividade, 1, 2, 'Explique por que um assunto vago como "Urgente" prejudica a comunicação e o que o assunto padronizado resolve.', 0.5, 'Um assunto vago não informa do que se trata nem a prioridade; o e-mail é ignorado, demora a ser lido ou se perde na caixa de entrada e é difícil de encontrar depois. O assunto padronizado identifica o setor, o tema e o prazo, permite priorizar, organizar e localizar a mensagem (o e-mail é um registro oficial).', 'Nota cheia: explica o problema do assunto vago e a vantagem do padronizado. Metade: só um dos lados. Zero: resposta genérica sem relação.'),
      (v_atividade, 2, 1, 'Escreva a saudação e o corpo do e-mail, com todas as informações de que a transportadora precisa (pedido, quantidade, peso, destino, data, horário e local).', 0.6, 'Saudação formal ("Prezado Sr. Marcos Lima,"). Corpo direto e conciso solicitando o agendamento da coleta do pedido 4587: 12 paletes, 3.400 kg, destino Blumenau, carga liberada em 03/10 a partir das 8h, na doca 2 da Distribuidora Vale Sul. Pedido de confirmação do agendamento (feedback).', 'Nota cheia: saudação formal e as sete informações (pedido, quantidade, peso, destino, data, horário, local), em tom profissional. Metade: saudação adequada e quatro a seis informações, ou todas as informações com linguagem informal. Zero: três informações ou menos, ou sem relação com o caso.'),
      (v_atividade, 2, 2, 'Escreva o fechamento com a assinatura institucional completa.', 0.4, 'Despedida formal ("Atenciosamente" ou "Cordialmente"), nome completo, cargo (Assistente de Operações Logísticas – Expedição), empresa (Distribuidora Vale Sul Logística) e contato (telefone/ramal ou e-mail institucional).', 'Nota cheia: despedida formal + nome + cargo/setor + empresa ou contato. Metade: despedida formal com assinatura incompleta. Zero: sem despedida/assinatura ou com gíria ("vlw", "abs").'),
      (v_atividade, 3, 1, 'Indique em qual campo (Para, CC ou CCO) ficam o Sr. Marcos e a supervisora Ana, explicando a função de cada campo.', 0.5, 'Sr. Marcos no campo Para, porque é o destinatário principal, de quem se espera a ação (agendar a coleta). Supervisora Ana em CC, porque só acompanha e fica informada, sem resposta obrigatória.', 'Nota cheia: os dois campos certos com a função de cada um. Metade: campos certos sem explicar, ou um campo certo explicado. Zero: campos trocados.'),
      (v_atividade, 3, 2, 'Indique o campo correto para os 30 clientes e explique o risco de usar outro campo.', 0.5, 'Os 30 clientes devem ir em CCO (cópia oculta). Se forem em Para ou CC, todos veem os e-mails dos outros clientes: vazamento de dados pessoais/contatos, descumprimento da LGPD, risco de spam e de "responder a todos" em massa.', 'Nota cheia: CCO + risco de expor os endereços (privacidade/LGPD). Metade: CCO sem explicar o risco. Zero: Para ou CC.'),
      (v_atividade, 4, 1, 'Escreva um novo nome padronizado para o romaneio e indique em qual formato ele deve ser enviado, justificando.', 0.5, 'Nome padronizado com data, descrição e versão, sem espaços e acentos, ex.: "2026-10-03_Romaneio_Pedido4587_v01.pdf". Enviar em PDF, formato universal de documento final, que abre em qualquer dispositivo e não é alterado sem querer.', 'Nota cheia: nome descritivo padronizado (com data e/ou versão) + PDF justificado. Metade: só um dos dois corretos. Zero: nome genérico e formato sem justificativa.'),
      (v_atividade, 4, 2, 'Explique como você enviaria as 25 fotos e o que deve ser escrito no corpo do e-mail sobre os arquivos.', 0.5, 'Como passa de 20 MB, as fotos não vão como anexo (podem ser bloqueadas): colocar numa pasta da nuvem e enviar o link com permissão de Leitor. No corpo do e-mail, citar que há um anexo (o romaneio) e um link com as fotos, dizendo o que cada um contém.', 'Nota cheia: link da nuvem por causa do tamanho + citar anexo/link no corpo. Metade: um dos dois. Zero: anexar os 35 MB sem comentário ou resposta sem relação.'),
      (v_atividade, 5, 1, 'Aponte pelo menos quatro erros de netiqueta ou de linguagem presentes na mensagem e no envio.', 0.5, 'Entre os erros: e-mail sem assunto; texto todo em CAPS LOCK (equivale a gritar); gírias e saudação informal ("E aí, beleza?"); abreviações ("vcs", "qq", "vlw"); culpar a transportadora/expor terceiros em vez de focar na solução; falta de informações (qual carga, nova previsão); sem assinatura; uso indevido de "Responder a todos".', 'Nota cheia: quatro erros ou mais. Metade: dois ou três. Zero: um ou nenhum.'),
      (v_atividade, 5, 2, 'Reescreva o e-mail completo (assunto, saudação, corpo e fechamento) de forma profissional.', 0.5, 'E-mail com assunto claro (ex.: "[Expedição - Pedido NNNN] Atraso na entrega – Nova previsão"), saudação formal, explicação objetiva do atraso sem culpar terceiros, nova previsão ou compromisso de informar, pedido de desculpas/disponibilidade, despedida formal e assinatura, sem caixa alta e sem gírias.', 'Nota cheia: assunto, saudação, corpo profissional e fechamento com assinatura. Metade: texto profissional faltando uma ou duas dessas partes. Zero: mantém CAPS LOCK/gírias ou não reescreve.'),
      (v_atividade, 6, 1, 'Escreva a árvore de pastas que você criaria (pasta principal e subpastas), usando as etapas Rascunhos, Revisão e Final.', 0.5, 'Exemplo: Expedição/2026/2026-10_Outubro/ com subpastas Rascunhos, Revisão e Final (e, se quiser, Romaneios, Planilhas, Fotos). A estrutura vai do geral (ano) para o específico (mês/projeto) e separa as etapas do documento.', 'Nota cheia: pasta principal por ano/mês ou projeto + as três subpastas de etapa. Metade: estrutura com só parte das etapas ou sem hierarquia clara. Zero: sem estrutura.'),
      (v_atividade, 6, 2, 'Escreva o nome padronizado do romaneio do pedido 4587, versão 2, usando a data no formato AAAA-MM-DD, e explique por que esse formato de data é usado.', 0.5, 'Ex.: "2026-10-03_Romaneio_Pedido4587_v02.pdf". O formato AAAA-MM-DD faz os arquivos ficarem em ordem cronológica automática quando ordenados por nome e evita ambiguidade de datas.', 'Nota cheia: nome com data AAAA-MM-DD, pedido e versão 2 + explica a ordenação. Metade: nome correto sem explicação, ou explicação com nome incompleto. Zero: data em outro formato e sem explicação.'),
      (v_atividade, 7, 1, 'Indique a permissão (Leitor, Comentador ou Editor) de cada pessoa ou grupo e justifique cada escolha.', 0.6, 'Conferentes: Editor (precisam alterar a planilha). Transportadora Rápido Sul: Leitor (só consulta e baixa os romaneios; é externa). Coordenadora de qualidade: Comentador (sugere correções sem alterar os dados). Princípio do menor privilégio.', 'Nota cheia: as três permissões certas com justificativa. Metade: duas certas, ou três certas sem justificar. Zero: uma ou nenhuma.'),
      (v_atividade, 7, 2, 'Explique por que você não deve compartilhar a pasta com um link público de edição.', 0.4, 'Com link público de edição, qualquer pessoa que tiver o link (inclusive de fora da empresa) pode ver, alterar ou apagar os arquivos: risco de vazamento de dados de clientes, sabotagem, perda de arquivos e descumprimento da LGPD e das normas da empresa. O certo é compartilhar com os e-mails das pessoas e o nível mínimo necessário.', 'Nota cheia: cita o acesso de qualquer pessoa + pelo menos um risco (vazamento/alteração/exclusão). Metade: só diz que "é perigoso" sem explicar. Zero: sem relação.'),
      (v_atividade, 8, 1, 'Explique o que acontece com as alterações que você fez sem internet e como os ícones de status mostram a situação do arquivo.', 0.5, 'As alterações ficam salvas na pasta local; quando a internet volta, a sincronização envia automaticamente as mudanças para a nuvem, deixando as cópias iguais. Ícones: setas circulares = sincronizando/enviando; check verde = arquivo disponível e atualizado no computador; nuvem = arquivo só na nuvem.', 'Nota cheia: explica a sincronização ao reconectar + pelo menos dois ícones. Metade: só um dos dois. Zero: diz que as alterações se perdem.'),
      (v_atividade, 8, 2, 'Descreva os passos para recuperar a planilha apagada e como evitar confusão entre versões no futuro.', 0.5, 'Abrir a planilha na nuvem, acessar o Histórico de versões, escolher a versão anterior à exclusão (data/hora), conferir e restaurar. Para evitar confusão: nomear as versões importantes (ex.: "Fechamento 03/10"), usar a edição colaborativa num único arquivo em vez de cópias por anexo e dar permissão de edição só a quem precisa.', 'Nota cheia: passos do histórico de versões + uma medida de prevenção. Metade: só um dos dois. Zero: refazer a planilha à mão ou resposta sem relação.'),
      (v_atividade, 9, 1, 'Escreva o comentário que você deixaria na célula, com a menção ao Pedro, o que ele deve fazer e o prazo, e diga o que fazer com o comentário depois da correção.', 0.5, 'Ex.: "@pedro.souza@valesul.com.br (ou +Pedro Souza), o peso do pedido 4590 está em branco. Pode conferir na balança e preencher até as 16h de hoje? Obrigado!". Depois da correção, clicar em Resolver para fechar o comentário e manter o documento organizado.', 'Nota cheia: menção ao Pedro + tarefa clara + prazo + "Resolver". Metade: faltam um ou dois desses elementos. Zero: sem menção nem tarefa.'),
      (v_atividade, 9, 2, 'Em vez de mandar só "Oi, Pedro, tudo bem?" no chat, escreva uma mensagem completa e autoexplicativa e explique por que ela é melhor no trabalho assíncrono.', 0.5, 'Ex.: "Bom dia, Pedro. O peso do pedido 4590 está em branco na planilha de cargas (aba Expedição). Preciso dele até as 16h para fechar o romaneio. Deixei um comentário na célula. Obrigado!". Na comunicação assíncrona a pessoa lê depois; a mensagem completa evita esperar resposta ao "Oi", economiza tempo e evita mal-entendidos.', 'Nota cheia: mensagem completa (o quê, onde, prazo) + justificativa assíncrona. Metade: só um dos dois. Zero: mantém só a saudação.'),
      (v_atividade, 10, 1, 'Descreva as ações imediatas para proteger a pasta e recuperar os romaneios, e como orientar o colega que criou o link.', 0.5, 'Remover o link público ou mudar para acesso restrito, compartilhar só com os e-mails da equipe com a permissão certa, consultar o histórico de versões/atividades (logs) para ver quem apagou e restaurar os romaneios, avisar a supervisora. Orientar o colega com empatia e firmeza: explicar os riscos, as regras e a forma segura de trabalhar remotamente, sem humilhar ou culpar em público.', 'Nota cheia: restringe o acesso + recupera pelo histórico/lixeira + orienta com empatia. Metade: duas dessas ações. Zero: uma ou nenhuma, ou atitude agressiva com o colega.'),
      (v_atividade, 10, 2, 'Explique como o colega ofendido deve agir para denunciar o caso, citando os passos estudados e uma lei que protege os usuários.', 0.5, 'Documentar (prints com data, hora e remetente; guardar as mensagens/logs), não revidar e acionar os canais oficiais (supervisão, coordenação, RH ou canal de denúncia). Leis: Lei Carolina Dieckmann (Lei 12.737/2012) e/ou Marco Civil da Internet (Lei 12.965/2014).', 'Nota cheia: os três passos (documentar, não revidar, canal oficial) + uma lei. Metade: dois passos, ou passos sem a lei. Zero: um passo ou nenhum, ou sugere revidar.');
end $$;
